documents.nested_operands:
yamaa: "1.0"
type: spec
domain: TEST
keys: [ID]
input: {A: {path: a.csv, types: {D: date}}, B: {path: b.csv, key: [ID], types: {D: date}}}
base: A
output: {path: result.csv, columns: [ID, TEXT, DAYS]}
columns:
  - {name: ID, type: str, derivation: A.ID}
  - {name: TEXT, type: str}
  - {name: DAYS, type: int}
rows:
  - id: records
    dataset: A
    derivations:
      TEXT: {case: [{when: "A.USE = 'Y'", then: {str_case: {source: B.TEXT, to: upper}}}, {otherwise: "'SKIP'"}]}
      DAYS: {case: [{when: "A.USE = 'Y'", then: {diff: {type: date, start: B.D, end: A.D, unit: day}}}, {otherwise: 0}]}

documents.foreign_driver:
yamaa: "1.0"
type: spec
domain: TEST
keys: [ID]
input: {A: {path: a.csv, key: [ID]}, B: {path: b.csv, types: {N: int}}}
base: A
output: {path: result.csv, columns: [ID, TEXT, FLAG]}
columns:
  - {name: ID, type: str}
  - {name: TEXT, type: str}
  - {name: FLAG, type: str, derivation: {flag: "A.USE = 'Y'"}}
rows:
  - id: beta
    dataset: B
    derivations:
      ID: B.ID
      TEXT: {str_case: {source: A.TEXT, to: upper}}
